package dev.sgs.core.persistence;

import dev.sgs.core.card.CardType;
import dev.sgs.core.engine.*;
import dev.sgs.core.engine.TrickContinuation.*;
import dev.sgs.core.game.GameState.PublicSkillActivation;
import java.io.*;
import java.security.*;
import java.util.*;

/** Bounded versioned binary format; SHA256 detects corruption, not privileged file forgery. */
public final class TrickCheckpointCodec {
  private static final int MAGIC=0x53474354;
  public static final int MAX_BYTES=StateCheckpointCodec.MAX_BYTES+524288;
  private TrickCheckpointCodec(){}
  public static boolean isPayload(byte[] bytes){return bytes!=null&&bytes.length>=8&&java.nio.ByteBuffer.wrap(bytes).getInt()==MAGIC;}
  public static byte[] encode(TrickCheckpoint s){
    s.validate();try(var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes)){
      out.writeInt(MAGIC);out.writeInt(s.version());out.writeUTF(TrickCheckpoint.rulesVersion(s.version()));byte[] state=StateCheckpointCodec.encode(s.state());out.writeInt(state.length);out.write(state);
      out.writeLong(s.promptSequence());out.writeInt(s.responseTimeoutSeconds());out.writeLong(s.skillSequence());out.writeInt(s.activations().size());
      for(var a:s.activations()){out.writeLong(a.sequence());out.writeInt(a.seat());out.writeUTF(a.skillId());}
      out.writeInt(s.skillMemory().size());for(var entry:new TreeMap<>(s.skillMemory()).entrySet()){out.writeUTF(entry.getKey());out.writeInt(entry.getValue().size());for(var field:new TreeMap<>(entry.getValue()).entrySet()){out.writeUTF(field.getKey());out.writeLong(field.getValue());}}
      out.writeInt(s.bindings().size());for(var b:s.bindings())out.writeUTF(b);
      var c=s.continuation();out.writeInt(c.version());out.writeInt(c.source());out.writeInt(c.target());out.writeLong(c.cardId());out.writeUTF(c.effectiveType().name());out.writeUTF(c.step().name());out.writeInt(c.depth());out.writeLong(c.revision());
      out.writeInt(c.counters().size());for(var cost:c.counters()){out.writeInt(cost.seat());out.writeLong(cost.cardId());}seats(out,c.scopePassed());
      out.writeInt(c.movements().size());for(var m:c.movements()){out.writeLong(m.sequence());out.writeUTF(m.from().kind().name());out.writeInt(m.from().seat());out.writeUTF(m.to().kind().name());out.writeInt(m.to().seat());out.writeInt(m.cards().size());for(long id:m.cards())out.writeLong(id);out.writeUTF(m.reason().name());out.writeInt(m.actor());out.writeBoolean(m.publicCards());}
      out.writeBoolean(c.window()!=null);if(c.window()!=null){var w=c.window();out.writeLong(w.id());out.writeInt(w.subject());out.writeInt(w.depth());out.writeLong(w.deadline());out.writeInt(w.tokens().size());for(var t:w.tokens()){out.writeLong(t.id());out.writeInt(t.seat());}seats(out,w.pending());seats(out,w.passed());}
      out.writeBoolean(c.pending()!=null);if(c.pending()!=null){var p=c.pending();out.writeLong(p.id());out.writeUTF(p.type().name());out.writeInt(p.asker());out.writeInt(p.subject());out.writeLong(p.deadline());out.writeInt(p.choices().size());for(long id:p.choices())out.writeLong(id);out.writeBoolean(p.hidden());out.writeUTF(p.skill());out.writeLong(p.revision());}
      if(s.version()>=2){var f=c.family();seats(out,f.targets());out.writeInt(f.cursor());out.writeBoolean(f.revealed());out.writeInt(f.harvest().size());for(long id:f.harvest())out.writeLong(id);out.writeInt(f.duelResponder());out.writeInt(f.duelOther());out.writeInt(f.duelRequired());out.writeInt(f.duelPaid());out.writeBoolean(f.response()!=null);if(f.response()!=null)ContinuationFrameIO.response(out,f.response(),s.version());out.writeBoolean(f.damage()!=null);if(f.damage()!=null)ContinuationFrameIO.damage(out,f.damage());}
      if(s.version()>=3){out.writeBoolean(c.family().yiji()!=null);if(c.family().yiji()!=null)ContinuationFrameIO.yiji(out,c.family().yiji());}
      if(s.version()>=5){var f=c.family();out.writeBoolean(f.ganglie()!=null);if(f.ganglie()!=null)ContinuationFrameIO.ganglie(out,f.ganglie());out.writeInt(f.parents().size());for(var p:f.parents()){ContinuationFrameIO.damage(out,p.damage());ContinuationFrameIO.ganglie(out,p.ganglie());}}
      if(s.version()>=6){out.writeBoolean(c.family().movementPrepared());out.writeBoolean(c.family().feedbackTaken());out.writeBoolean(c.family().penaltyLogPending());}
      if(s.version()>=7){out.writeBoolean(c.family().program()!=null);if(c.family().program()!=null){byte[] program=DamageProgramCodec.encode(c.family().program());out.writeInt(program.length);out.write(program);}}
      if(s.version()>=9){var reveal=c.family().revealCost();out.writeBoolean(reveal!=null);if(reveal!=null){out.writeInt(reveal.source());out.writeInt(reveal.target());out.writeUTF(reveal.step().name());out.writeLong(reveal.shown());out.writeLong(reveal.cost());var p=reveal.pending();out.writeBoolean(p!=null);if(p!=null){out.writeLong(p.id());out.writeUTF(p.type().name());out.writeInt(p.asker());out.writeInt(p.subject());out.writeLong(p.deadline());out.writeInt(p.choices().size());for(long id:p.choices())out.writeLong(id);out.writeBoolean(p.hidden());out.writeUTF(p.skill());out.writeLong(p.revision());}}}
      if(s.version()>=10){var strike=c.family().strike();out.writeBoolean(strike!=null);if(strike!=null){out.writeUTF(strike.step().name());byte[] supply=AttackSupplyCodec.encode(strike.supply());out.writeInt(supply.length);out.write(supply);out.writeBoolean(strike.attack()!=null);if(strike.attack()!=null)ContinuationFrameIO.attack(out,strike.attack());}}
      if(s.version()>=11){var movement=c.family().movementProgram();out.writeBoolean(movement!=null);if(movement!=null){byte[] payload=MovementListenerCodec.encode(movement);out.writeInt(payload.length);out.write(payload);}}
      out.writeLong(s.capturedAtMillis());out.flush();byte[] data=bytes.toByteArray();if(data.length+32>MAX_BYTES)throw new IllegalArgumentException("trick checkpoint too large");bytes.write(digest(data));return bytes.toByteArray();
    }catch(IOException error){throw new IllegalArgumentException("cannot encode trick checkpoint",error);}
  }
  public static TrickCheckpoint decode(byte[] bytes){
    if(bytes==null || bytes.length<64 || bytes.length>MAX_BYTES)throw new IllegalArgumentException("invalid trick checkpoint size");
    byte[] data=Arrays.copyOf(bytes,bytes.length-32);if(!MessageDigest.isEqual(digest(data),Arrays.copyOfRange(bytes,bytes.length-32,bytes.length)))throw new IllegalArgumentException("trick checksum mismatch");
    try(var in=new DataInputStream(new ByteArrayInputStream(data))){
      if(in.readInt()!=MAGIC)throw new IllegalArgumentException("bad trick magic");int version=in.readInt();if(!in.readUTF().equals(TrickCheckpoint.rulesVersion(version)))throw new IllegalArgumentException("trick rules mismatch");
      int length=count(in,StateCheckpointCodec.MAX_BYTES);byte[] payload=in.readNBytes(length);if(payload.length!=length)throw new EOFException();var state=StateCheckpointCodec.decode(payload);
      long sequence=in.readLong();int timeout=in.readInt();long skillSequence=in.readLong();var events=new ArrayList<PublicSkillActivation>();int size=count(in,32);for(int i=0;i<size;i++)events.add(new PublicSkillActivation(in.readLong(),in.readInt(),in.readUTF()));
      var memory=new TreeMap<String,Map<String,Long>>();size=count(in,SkillMemoryLayout.MAX_RECORDS);for(int i=0;i<size;i++){String key=in.readUTF();int fields=count(in,8);var values=new TreeMap<String,Long>();for(int j=0;j<fields;j++)if(values.put(in.readUTF(),in.readLong())!=null)throw new IllegalArgumentException("duplicate trick memory field");if(memory.put(key,values)!=null)throw new IllegalArgumentException("duplicate trick memory");}
      var bindings=new ArrayList<String>();size=count(in,256);for(int i=0;i<size;i++)bindings.add(in.readUTF());
      int frameVersion=in.readInt(),source=in.readInt(),target=in.readInt();long card=in.readLong();var type=CardType.valueOf(in.readUTF());var step=Step.valueOf(in.readUTF());int depth=in.readInt();long revision=in.readLong();
      var costs=new ArrayList<Cost>();size=count(in,160);for(int i=0;i<size;i++)costs.add(new Cost(in.readInt(),in.readLong()));var passed=seats(in);
      var movements=new ArrayList<Movement>();size=count(in,512);for(int i=0;i<size;i++){long seq=in.readLong();var from=new dev.sgs.core.card.CardZone(dev.sgs.core.card.CardZone.Kind.valueOf(in.readUTF()),in.readInt());var to=new dev.sgs.core.card.CardZone(dev.sgs.core.card.CardZone.Kind.valueOf(in.readUTF()),in.readInt());var cards=new ArrayList<Long>();int count=count(in,4096);for(int j=0;j<count;j++)cards.add(in.readLong());movements.add(new Movement(seq,from,to,cards,dev.sgs.core.card.CardMove.Reason.valueOf(in.readUTF()),in.readInt(),bool(in)));}
      Window window=null;if(bool(in)){long id=in.readLong();int subject=in.readInt(),chain=in.readInt();long deadline=in.readLong();var tokens=new ArrayList<Token>();size=count(in,8);for(int i=0;i<size;i++)tokens.add(new Token(in.readLong(),in.readInt()));window=new Window(id,subject,chain,deadline,tokens,seats(in),seats(in));}
      Pending pending=null;if(bool(in)){long id=in.readLong();var prompt=PromptType.valueOf(in.readUTF());int asker=in.readInt(),subject=in.readInt();long deadline=in.readLong();var choices=new ArrayList<Long>();size=count(in,160);for(int i=0;i<size;i++)choices.add(in.readLong());pending=new Pending(id,prompt,asker,subject,deadline,choices,bool(in),in.readUTF(),in.readLong());}
      Family family=null;if(version>=2){var targets=seats(in);int cursor=in.readInt();boolean revealed=bool(in);var harvest=new ArrayList<Long>();size=count(in,8);for(int i=0;i<size;i++)harvest.add(in.readLong());int duelResponder=in.readInt(),duelOther=in.readInt(),duelRequired=in.readInt(),duelPaid=in.readInt();var response=bool(in)?ContinuationFrameIO.response(in,version):null;var damage=bool(in)?ContinuationFrameIO.damage(in):null;family=new Family(targets,cursor,revealed,harvest,duelResponder,duelOther,duelRequired,duelPaid,response,damage);}
      if(version>=3 && bool(in)){var yiji=ContinuationFrameIO.yiji(in);family=new Family(family.targets(),family.cursor(),family.revealed(),family.harvest(),family.duelResponder(),family.duelOther(),family.duelRequired(),family.duelPaid(),family.response(),family.damage(),yiji);}
      if(version>=5){var ganglie=bool(in)?ContinuationFrameIO.ganglie(in):null;var parents=new ArrayList<DamageParentSnapshot>();size=count(in,64);for(int i=0;i<size;i++)parents.add(new DamageParentSnapshot(ContinuationFrameIO.damage(in),ContinuationFrameIO.ganglie(in)));family=new Family(family.targets(),family.cursor(),family.revealed(),family.harvest(),family.duelResponder(),family.duelOther(),family.duelRequired(),family.duelPaid(),family.response(),family.damage(),family.yiji(),ganglie,parents);}
      if(version>=6)family=new Family(family.targets(),family.cursor(),family.revealed(),family.harvest(),family.duelResponder(),family.duelOther(),family.duelRequired(),family.duelPaid(),family.response(),family.damage(),family.yiji(),family.ganglie(),family.parents(),bool(in),bool(in),bool(in));
      if(version>=7&&bool(in)){int lengthProgram=count(in,DamageProgramCodec.MAX_BYTES);byte[] program=in.readNBytes(lengthProgram);if(program.length!=lengthProgram)throw new EOFException();family=new Family(family.targets(),family.cursor(),family.revealed(),family.harvest(),family.duelResponder(),family.duelOther(),family.duelRequired(),family.duelPaid(),family.response(),family.damage(),family.yiji(),family.ganglie(),family.parents(),family.movementPrepared(),family.feedbackTaken(),family.penaltyLogPending(),DamageProgramCodec.decode(program));}
      if(version>=9&&bool(in)){int actor=in.readInt(),victim=in.readInt();var phase=RevealCostContinuation.Step.valueOf(in.readUTF());long shown=in.readLong(),cost=in.readLong();Pending p=null;if(bool(in)){long id=in.readLong();var prompt=PromptType.valueOf(in.readUTF());int asker=in.readInt(),subject=in.readInt();long deadline=in.readLong();var choices=new ArrayList<Long>();size=count(in,1);for(int i=0;i<size;i++)choices.add(in.readLong());p=new Pending(id,prompt,asker,subject,deadline,choices,bool(in),in.readUTF(),in.readLong());}var f=family;family=new Family(f.targets(),f.cursor(),f.revealed(),f.harvest(),f.duelResponder(),f.duelOther(),f.duelRequired(),f.duelPaid(),f.response(),f.damage(),f.yiji(),f.ganglie(),f.parents(),f.movementPrepared(),f.feedbackTaken(),f.penaltyLogPending(),f.program(),new RevealCostContinuation.Snapshot(actor,victim,phase,shown,cost,p));}
      if(version>=10&&bool(in)){var phase=StrikeContinuation.Step.valueOf(in.readUTF());int n=count(in,8192);byte[] b=in.readNBytes(n);if(b.length!=n)throw new EOFException();var supply=AttackSupplyCodec.decode(b);var attack=bool(in)?ContinuationFrameIO.attack(in):null;var f=family;family=new Family(f.targets(),f.cursor(),f.revealed(),f.harvest(),f.duelResponder(),f.duelOther(),f.duelRequired(),f.duelPaid(),f.response(),f.damage(),f.yiji(),f.ganglie(),f.parents(),f.movementPrepared(),f.feedbackTaken(),f.penaltyLogPending(),f.program(),f.revealCost(),new StrikeContinuation.Snapshot(phase,supply,attack));}
      if(version>=11&&bool(in)){int n=count(in,MovementListenerCodec.MAX_BYTES);byte[] b=in.readNBytes(n);if(b.length!=n)throw new EOFException();var f=family;family=new Family(f.targets(),f.cursor(),f.revealed(),f.harvest(),f.duelResponder(),f.duelOther(),f.duelRequired(),f.duelPaid(),f.response(),f.damage(),f.yiji(),f.ganglie(),f.parents(),f.movementPrepared(),f.feedbackTaken(),f.penaltyLogPending(),f.program(),f.revealCost(),f.strike(),MovementListenerCodec.decode(b));}
      long captured=in.readLong();if(in.available()!=0)throw new IllegalArgumentException("trailing trick data");var frame=new Snapshot(frameVersion,source,target,card,type,step,depth,costs,passed,movements,window,pending,revision,family);
      var saved=new TrickCheckpoint(version,state,sequence,timeout,memory,bindings,skillSequence,events,frame,captured);saved.validate();return saved;
    }catch(IOException|RuntimeException error){throw new IllegalArgumentException("invalid trick checkpoint: "+error.getMessage(),error);}
  }
  private static void seats(DataOutputStream out,List<Integer> values)throws IOException{out.writeInt(values.size());for(int v:values)out.writeInt(v);}
  private static List<Integer> seats(DataInputStream in)throws IOException{int n=count(in,8);var values=new ArrayList<Integer>();for(int i=0;i<n;i++)values.add(in.readInt());return values;}
  private static int count(DataInputStream in,int max)throws IOException{int n=in.readInt();if(n<0||n>max)throw new IllegalArgumentException("invalid trick collection length");return n;}
  private static boolean bool(DataInputStream in)throws IOException{int b=in.readUnsignedByte();if(b>1)throw new IllegalArgumentException("invalid trick boolean");return b==1;}
  private static byte[] digest(byte[] data){try{return MessageDigest.getInstance("SHA-256").digest(data);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
